-- Index, updated_at trigger, row-level security for every data table. Writes are limited by role through can_write();
-- there is no delete policy: rows are soft-deleted (deleted_at) so other devices learn about the deletion.
do $$ declare r record; begin
  for r in select * from (values
    ('suppliers', array['inventory','finance']),
    ('customers', array['finance']),
    ('fields', array['agriculture']),
    ('crops', array['agriculture']),
    ('planting_records', array['agriculture']),
    ('fertilizer_records', array['agriculture']),
    ('crop_protection_records', array['agriculture']),
    ('irrigation_records', array['agriculture']),
    ('harvest_records', array['agriculture']),
    ('crop_diagnoses', array['agriculture']),
    ('pastures', array['livestock']),
    ('animals', array['livestock']),
    ('weight_records', array['livestock']),
    ('grazing_records', array['livestock']),
    ('health_records', array['livestock']),
    ('vaccination_records', array['livestock']),
    ('disease_records', array['livestock']),
    ('quarantine_records', array['livestock']),
    ('vet_appointments', array['livestock']),
    ('feed_inventory', array['livestock','inventory']),
    ('feed_consumption', array['livestock','inventory']),
    ('feedlot_records', array['livestock']),
    ('livestock_purchases', array['livestock']),
    ('livestock_sales', array['livestock']),
    ('breeding_records', array['livestock']),
    ('birth_records', array['livestock']),
    ('mortality_records', array['livestock']),
    ('employees', array['employees']),
    ('attendance', array['employees']),
    ('performance_reviews', array['employees']),
    ('salary_payments', array['employees']),
    ('tasks', array['tasks']),
    ('income', array['finance']),
    ('expenses', array['finance']),
    ('budgets', array['finance']),
    ('inventory', array['inventory']),
    ('documents', array['documents']),
    ('map_features', array['map']),
    ('notification_prefs', array['notifications'])
  ) as x(tbl, areas) loop
    execute format('create index on public.%I (farm_id, updated_at)', r.tbl);
    execute format('create trigger %I before insert or update on public.%I for each row execute function public.touch_row()', r.tbl || '_touch', r.tbl);
    execute format('alter table public.%I enable row level security', r.tbl);
    execute format('create policy %I on public.%I for select using (public.farm_role_of(farm_id) is not null)', r.tbl || '_read', r.tbl);
    execute format('create policy %I on public.%I for insert with check (public.can_write_any(farm_id, %L::text[]))', r.tbl || '_insert', r.tbl, r.areas);
    execute format('create policy %I on public.%I for update using (public.can_write_any(farm_id, %L::text[])) with check (public.can_write_any(farm_id, %L::text[]))', r.tbl || '_update', r.tbl, r.areas, r.areas);
  end loop;
end $$;

create unique index animals_farm_tag_uniq on public.animals (farm_id, lower(tag)) where deleted_at is null;

-- One round trip to fetch everything that changed on a farm (RLS applies: runs as the caller).
create or replace function public.farm_changes(f uuid, since timestamptz default null, lim int default 5000) returns jsonb language plpgsql stable as $fn$
declare t text; r jsonb; res jsonb := '{}'::jsonb; more jsonb := '[]'::jsonb;
begin
  foreach t in array array['suppliers','customers','fields','crops','planting_records','fertilizer_records','crop_protection_records','irrigation_records','harvest_records','crop_diagnoses','pastures','animals','weight_records','grazing_records','health_records','vaccination_records','disease_records','quarantine_records','vet_appointments','feed_inventory','feed_consumption','feedlot_records','livestock_purchases','livestock_sales','breeding_records','birth_records','mortality_records','employees','attendance','performance_reviews','salary_payments','tasks','income','expenses','budgets','inventory','documents','map_features','notification_prefs'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at, x.id), ''[]''::jsonb) from (select * from public.%I where farm_id = $1 and ((($2)::timestamptz is null and deleted_at is null) or updated_at >= ($2)::timestamptz) order by updated_at, id limit $3) x', t) into r using f, since, lim + 1;
    if jsonb_array_length(r) > lim then more := more || to_jsonb(t); r := r - lim; end if;
    if jsonb_array_length(r) > 0 then res := res || jsonb_build_object(t, r); end if;
  end loop;
  return jsonb_build_object('tables', res, 'more', more);
end $fn$;
